    const outstanding = inv.amountCurrencyOutstanding ?? inv.amountOutstanding ?? "?";
    console.log(`  Inv #${inv.invoiceNumber}: total=${inv.amount} outstanding=${outstanding} ${outstanding === 0 || outstanding === 0.0 ? "✓ PAID" : "⚠ STILL OUTSTANDING"}`);
